    root_file = _compose_path(args, "root_cause_file", tmpdir, _DEFAULT_ROOT_CAUSE_FILE, prefix)
    bounded_file = _compose_path(args, "bounded_root_cause_file", tmpdir, _DEFAULT_BOUNDED_ROOT_CAUSE_FILE, prefix)
