        f"| Dispatcher | `{_safe_simple_token(read_kv(class_file, 'DISPATCHER', ''), fallback='unknown')}` |",
        f"| Matched classifier pattern | `{_safe_simple_token(read_kv(class_file, 'MATCHED_CLASSIFIER_PATTERN', ''), fallback='redacted')}` |",
