        f"| Root-cause confidence | `{_parse_root_cause_file(root_file, 'confidence', '')}` |",
        "",
        "## Bounded root-cause summary",
        "",
        summary,
        "",
        "## Bounded root-cause details",
        "",
        _root_cause_prose(bounded_file),
        "",
        "## Attempts",
        "",
